SELECT CASE WHEN budget >= 4051000 THEN 'high' WHEN budget >= 1798000 THEN 'mid' ELSE 'low' END AS budget_bucket, ROUND((100 * SUM(CASE WHEN location = 'Singapore' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_singapore FROM departments WHERE location IN ('London', 'Bangkok') GROUP BY CASE WHEN budget >= 4051000 THEN 'high' WHEN budget >= 1798000 THEN 'mid' ELSE 'low' END ORDER BY pct_singapore DESC;
